// Revue éditoriale exercice par exercice. La fiche BMF fournie guide les questions
// pédagogiques ; ces contenus et dosages sont des propositions du club, pas une
// validation FFF. Les schémas et animations restent liés aux effectifs calculés.
const exercisePedagogy={
 warm:{family:'activation',task:'Conduire dans un espace libre sans collision, puis changer de direction après une prise d’information.',observe:'La tête se lève avant le changement de direction, sans arrêter la maîtrise du ballon.',question:'Quel espace avais-tu repéré avant de tourner ?',correction:'Ralentir la conduite et faire désigner l’espace libre avant le changement de direction.',invariant:'Un ballon par joueur, aucun défenseur et aucune file. Ne pas ajouter de passe à un exercice de conduite individuelle.',easier:'Conduite lente, touches libres et un seul signal visuel.',harder:'Changer la surface de contact après avoir annoncé une information visuelle, sans imposer une accélération maximale.'},
 cool:{family:'recovery',task:'Échanger doucement puis décrire une action réussie et un point à reprendre.',observe:'Chaque petit groupe donne un exemple concret du travail réalisé, sans nouvelle opposition.',question:'Quelle décision t’a aidé aujourd’hui, et à quel moment du match pourrait-elle servir ?',correction:'Repartir d’une action vécue plutôt que demander de réciter un principe abstrait.',invariant:'Aucune course intense ni défi chronométré ; le rangement reste séparé des échanges avec ballon.',easier:'Bilan par binômes avant une restitution courte.',harder:'Faire expliquer pourquoi une autre décision aurait été moins adaptée, sans ajouter de charge physique.'},
 passes:{family:'technical',task:'Transmettre au poste suivant et rejoindre le poste libéré sans couper la passe suivante.',observe:'Le premier contact prépare la transmission et le joueur suivant est prêt avant le ballon.',question:'Vers quel poste ton premier contact doit-il t’ouvrir ?',correction:'Rejouer à vitesse réduite : contrôle vers le poste suivant, passe accessible, déplacement après le départ du ballon.',invariant:'Trois postes et un ballon par circuit. Les joueurs supplémentaires doublent un poste ; pas de défenseur dans ce format technique.',easier:'Raccourcir les passes et autoriser contrôle puis passe.',harder:'Alterner le sens du circuit ; choisir remise directe ou contrôle selon la qualité du service, sans obligation d’une touche.'},
 rondo:{family:'possession',task:'Conserver autour des défenseurs ; les défenseurs cherchent une interception maîtrisée.',observe:'Le porteur dispose de deux lignes de passe distinctes avant de recevoir.',question:'Où te déplacer pour ne plus être caché par le défenseur ?',correction:'Figer avant la passe, décaler un soutien de quelques pas puis rejouer avec le même défenseur actif.',invariant:'Conserver une supériorité numérique réelle. Les défenseurs changent à la pause, sans sanctionner automatiquement le joueur qui perd le ballon.',easier:'Touches libres et espace légèrement agrandi, sans modifier les équipes.',harder:'Réduire une seule dimension si les angles restent disponibles ; ne pas ajouter un défenseur sans recalculer les rôles.'},
 triangle:{family:'opposition',task:'Progresser vers la porte en utilisant une remise lorsque le joueur d’appui ne peut pas se retourner.',observe:'Le troisième joueur se rend disponible pendant la première passe et reçoit face au jeu.',question:'L’appui peut-il se retourner ou a-t-il besoin d’une remise ?',correction:'Rejouer un temps avant la remise ; déplacer le troisième hors de l’alignement du défenseur.',invariant:'Au moins trois partenaires impliqués dans la relation passeur–appui–troisième. La combinaison est une possibilité, jamais une obligation si le jeu direct est ouvert.',easier:'Retarder la pression sur la première réception ; conserver les mêmes partenaires.',harder:'Libérer la pression dès la première passe et laisser le choix entre jeu direct, remise et conservation.'},
 build:{family:'opposition',task:'Les bleus sortent par la porte opposée ; les rouges récupèrent puis attaquent la porte de départ.',observe:'Le receveur offre un angle visible et conserve une solution de retour quand l’avant se ferme.',question:'Quelle sortie est libre, et qui sécurise si elle se ferme ?',correction:'Replacer un soutien bas et un relais plus haut ; rejouer le départ sans imposer la passe.',invariant:'Deux sens de jeu et deux portes. Le gardien éventuellement présent joue au pied dans ce format, pas dans un but ajouté au dessin.',easier:'Déclencher le pressing après le premier contrôle.',harder:'Pression immédiate à la mise en jeu ; conserver les mêmes portes et autoriser le contre.'},
 press:{family:'opposition',task:'Les rouges ferment la progression puis attaquent la porte adverse après récupération.',observe:'La sortie du premier presseur est accompagnée d’une couverture intérieure.',question:'Quel signal te permet de sortir, et qui protège derrière toi ?',correction:'Figer sur une passe latérale ; faire nommer le presseur et sa couverture avant de rejouer.',invariant:'Un signal de pressing partagé ; si le rideau est battu, se réorganiser au lieu de poursuivre isolément.',easier:'Annoncer un seul déclencheur : passe latérale lente.',harder:'Laisser reconnaître le déclencheur sans annonce ; les bleus peuvent changer de côté.'},
 trap:{family:'opposition',task:'Orienter la relance vers un côté, récupérer à plusieurs puis ressortir vers la porte opposée.',observe:'La course du premier défenseur ferme l’axe et le deuxième protège la sortie intérieure.',question:'Quelle passe veux-tu laisser, et quelle passe dois-tu fermer ?',correction:'Rejouer la passe vers le côté en corrigeant l’angle de course et la distance de couverture.',invariant:'Les couloirs sont des repères, pas des cages. La couverture doit pouvoir réagir au renversement.',easier:'Commencer toujours du même côté avec un déclencheur connu.',harder:'Alterner le côté de départ et laisser les relanceurs renverser librement.'},
 cover:{family:'opposition',task:'Ralentir l’attaque vers la porte tout en couvrant la sortie du partenaire.',observe:'Le deuxième défenseur reste derrière et à l’intérieur du premier, à une distance permettant d’intervenir.',question:'Si ton partenaire est éliminé maintenant, peux-tu défendre la suite ?',correction:'Figer le duel ; reculer et décaler la couverture, puis rejouer la même approche.',invariant:'Au moins deux défenseurs dans l’action. Cadrage et couverture ne sont pas deux courses simultanées vers le ballon.',easier:'Attaque à rythme maîtrisé, départ frontal et espace lisible.',harder:'Changer le côté du service et laisser l’attaque choisir passe ou conduite.'},
 block:{family:'opposition',task:'Protéger la porte axiale, coulisser avec le ballon puis progresser après récupération.',observe:'Les défenseurs se déplacent ensemble sans ouvrir un intervalle direct vers la cible.',question:'Quel intervalle s’ouvre quand tu sors de la ligne ?',correction:'Figer le renversement et rapprocher les partenaires concernés, sans faire reculer tout le bloc sur sa porte.',invariant:'Le bloc doit avoir plusieurs défenseurs reliés ; un simple duel ne représente pas le coulissement collectif annoncé.',easier:'Circulation adverse plus lente et départ du même côté.',harder:'Laisser le porteur choisir conduite, passe intérieure ou changement de côté.'},
 transition:{family:'transition',task:'Conserver ; dès la perte, gêner le nouveau porteur et fermer ses passes proches.',observe:'Le proche ralentit pendant qu’un partenaire ferme une solution, au lieu de courir tous sur le ballon.',question:'Peut-on presser ensemble ou faut-il d’abord se replacer ?',correction:'Revenir à l’instant de la perte et répartir pression du proche et fermeture d’une passe.',invariant:'Le jeu continue au changement de possession ; pas de remise au coach à chaque interception.',easier:'Touches libres et distances permettant une réaction collective.',harder:'Laisser les deux équipes exploiter immédiatement la récupération sans rappel du coach.'},
 counter:{family:'transition',task:'Après récupération, attaquer le mini-but disponible ; conserver si l’avantage a disparu.',observe:'La première décision trouve une sortie de pression et les appels occupent deux hauteurs.',question:'L’adversaire est-il désorganisé ou déjà replacé ?',correction:'Rejouer la récupération avec un soutien proche et un appel profond, sans exiger une passe vers l’avant.',invariant:'Deux mini-buts et changement immédiat de statut ; le contre n’est pas un sprint obligatoire à chaque gain.',easier:'Ralentir le retour défensif au départ de la répétition.',harder:'Récupération non annoncée et défense libre de se replier immédiatement.'},
 switch:{family:'opposition',task:'Attaquer l’une des deux portes adverses et changer de côté si la pression ferme le passage proche.',observe:'Le joueur éloigné reste visible ; le relais regarde le côté opposé avant de recevoir.',question:'As-tu réellement attiré un défenseur avant de renverser ?',correction:'Figer la pression d’un côté, montrer le soutien intermédiaire et rejouer sans imposer le renversement.',invariant:'Quatre portes, deux par sens. Le renversement est utile s’il libère une progression, pas pour respecter un circuit.',easier:'Touches libres et temps de préparation de la passe.',harder:'Retirer le bonus et observer si la cible éloignée est encore choisie au bon moment.'},
 overlap:{family:'opposition',task:'Fixer sur un côté puis exploiter l’appel du partenaire ou conserver si le passage se ferme.',observe:'L’appel part après l’engagement du défenseur et reste dans un couloir différent du porteur.',question:'L’espace libre est-il à l’intérieur ou à l’extérieur du défenseur ?',correction:'Rejouer le départ de l’appel une seconde plus tard, en gardant le porteur libre de décider.',invariant:'Au moins un porteur, un soutien et une opposition ; les autres joueurs soutiennent ou couvrent, sans file cachée.',easier:'Défenseur retardé sur le premier contrôle.',harder:'Défense active et possibilité de contre vers la porte opposée.'},
 finish:{family:'finishing',task:'Recevoir, préparer la frappe et choisir tir ou passe selon l’opposition présente.',observe:'Le dernier contact ouvre un angle de frappe sans éloigner le ballon du joueur.',question:'Ton premier contact prépare-t-il le tir ou te ferme-t-il l’angle ?',correction:'Rejouer le service et orienter le contrôle vers une zone de frappe libre avant de retrouver le défenseur.',invariant:'Les défenseurs dessinés participent réellement ; sans gardien, la version à porte travaille la précision et non la finition face à un gardien.',easier:'Retarder la pression jusqu’au contrôle, sans retirer discrètement un défenseur.',harder:'Opposition active dès le service ; autoriser la remise si la frappe est fermée.'},
 cutback:{family:'finishing',task:'Atteindre le côté puis trouver une arrivée en retrait, disponible derrière la première ligne défensive.',observe:'Les deux receveurs arrivent à des hauteurs différentes ; le centreur regarde avant de donner.',question:'Qui arrive en retrait pendant que le premier attaquant entraîne la défense ?',correction:'Repartir avant le centre et retarder le receveur de retrait, sans figer les zones de finition.',invariant:'Un centreur et deux solutions complémentaires au minimum. Conserver si le centre est fermé.',easier:'Service au sol et pression retardée sur le centreur.',harder:'La défense choisit de fermer le retrait ou le premier poteau ; le centreur adapte son choix.'},
 duel:{family:'duel',task:'Franchir la porte disponible en maîtrisant le ballon ; après récupération, attaquer dans l’autre sens.',observe:'Le porteur change de rythme après avoir provoqué un déplacement du défenseur.',question:'De quel côté le défenseur te laisse-t-il un passage ?',correction:'Rejouer l’approche à distance utile ; le porteur fixe avant de choisir sa sortie.',invariant:'Le rapport réel est celui de la fiche adaptée : ne pas annoncer un 1 contre 1 si quatre joueurs jouent en même temps.',easier:'Départ plus éloigné et pression retardée.',harder:'Défenseur actif dès le service, avec contre conservé après récupération.'},
 support:{family:'opposition',task:'Recevoir entre les lignes puis relier un partenaire vers la cible, ou remettre si le retournement est fermé.',observe:'Le receveur sort de l’ombre avant la passe et vérifie sa prochaine solution.',question:'Peux-tu voir le porteur et la suite du jeu au même moment ?',correction:'Figer avant la passe ; décaler le receveur et rejouer avec les mêmes adversaires.',invariant:'Les tiers sont des repères ; le receveur n’est pas protégé artificiellement dans la version de base.',easier:'Pression retardée à la réception, touches libres.',harder:'Opposition libre et possibilité de conduire si la ligne s’ouvre.'},
 'cpa-attack':{family:'restart',task:'Attaquer des zones complémentaires sur corner tout en gardant une couverture du ballon repoussé.',observe:'Le signal et les courses sont synchronisés ; au moins un joueur est disponible pour la seconde action.',question:'Qui joue le second ballon si le premier centre est repoussé ?',correction:'Rejouer le signal sans contact, séparer les courses qui arrivent au même endroit puis réintroduire l’opposition.',invariant:'Ni blocage irrégulier ni gêne du gardien. La répétition ne commence qu’une fois tous les joueurs replacés.',easier:'Courses à vitesse maîtrisée et défense passive annoncée dans la première séquence.',harder:'Défense active et choix entre cible proche, éloignée ou corner court selon le placement.'},
 'cpa-defence':{family:'restart',task:'Protéger les zones dangereuses, jouer le ballon puis sortir ensemble sur la seconde action.',observe:'Chaque défenseur voit ballon et menace ; la sortie courte et le second ballon ont un responsable.',question:'Que protèges-tu si tu ne peux pas intervenir sur ce centre ?',correction:'Figer avant la livraison et faire annoncer les responsabilités avec le gardien.',invariant:'Pas de sortie collective avant le dégagement maîtrisé ; les missions dépendent du placement réellement dessiné.',easier:'Centre au sol ou trajectoire annoncée, sans duel aérien imposé.',harder:'Varier corner court et centre direct sans annoncer la cible.'},
 'keeper-feet':{family:'keeper-feet',task:'Le gardien trouve un soutien disponible puis reste une solution de retour.',observe:'Il regarde la pression avant réception et sa passe permet une action suivante au receveur.',question:'Quel partenaire sera encore libre quand ton ballon arrivera ?',correction:'Rejouer le service au gardien avec deux soutiens décalés et un seul déclencheur de pression.',invariant:'Un gardien réel par atelier et au moins deux soutiens. Les gardiens en rotation ne deviennent pas des joueurs de champ.',easier:'Pressing retardé jusqu’au premier contrôle.',harder:'Pressing immédiat et changement de côté possible par retour au gardien.'},
 'keeper-duel':{family:'keeper',task:'L’attaquant cherche le but ; le gardien ajuste distance, posture et moment d’intervention.',observe:'Le gardien réduit l’angle puis se stabilise au moment de la frappe, sans sortie tardive incontrôlée.',question:'À quelle distance peux-tu encore réagir au choix du porteur ?',correction:'Rejouer l’avant-dernière touche plus lentement puis reprendre avec une décision libre.',invariant:'Un seul ballon menaçant à la fois ; nouvelle action seulement quand le gardien est prêt. Aucun choc recherché.',easier:'Porteur ralenti et côté de départ connu.',harder:'Varier l’angle et laisser le choix passe ou frappe, sans accélération automatique de la cadence.'},
 touch:{family:'restart',task:'Conserver une touche par une solution courte, une profondeur ou un soutien disponible.',observe:'Les trois solutions ne se présentent pas dans le même alignement.',question:'Qui te donne une solution si la première remise est fermée ?',correction:'Figer avant le lancer ; échelonner trois partenaires puis rejouer une touche réglementaire.',invariant:'Le lanceur et trois solutions nécessitent au moins quatre attaquants ; remise à deux mains et pieds réglementaires.',easier:'Opposition retardée au premier contrôle.',harder:'Défense libre et poursuite de l’action vers la cible après réception.'},
 freegame:{family:'opposition',task:'Marquer dans la cible adverse en réutilisant librement le principe travaillé.',observe:'Le comportement recherché apparaît sans rappel permanent ni passage imposé.',question:'Quand as-tu retrouvé le problème travaillé dans ce jeu libre ?',correction:'Laisser une phase se terminer, puis revenir sur une décision précise plutôt que rajouter plusieurs règles.',invariant:'Un seul bonus éventuel, puis retrait du bonus. Le thème du coach doit être nommé avant le départ.',easier:'Conserver les touches libres et clarifier uniquement le sens de jeu.',harder:'Retirer les aides sans réduire automatiquement l’espace ni multiplier les contraintes.'},
 'scan-receive':{family:'technical',task:'Prendre une information avant réception puis orienter vers le poste suivant.',observe:'Le regard précède l’arrivée du ballon et le contrôle ouvre la prochaine passe.',question:'Qu’as-tu vu avant de recevoir ?',correction:'Ralentir le service ; faire regarder le prochain poste avant le premier contact.',invariant:'Trois postes par circuit ; l’information demandée doit être visible, pas une couleur annoncée au hasard derrière le joueur.',easier:'Contrôle autorisé et prochain poste connu.',harder:'Changer le sens au signal avant le service ; aucun signal tardif pendant le contrôle.'},
 'wall-pass':{family:'technical',task:'Donner, remettre puis servir dans la course avant une rotation par les retours extérieurs.',observe:'Le receveur arrive sur un ballon dosé et les joueurs libèrent le prochain poste.',question:'À quel moment le partenaire est-il prêt pour la remise ?',correction:'Rejouer sans vitesse ni saut ; synchroniser passe et disponibilité du receveur.',invariant:'Un ballon actif ; retours par l’échelle ou les haies séparés des passes. Pas de défenseur ajouté à ce circuit.',easier:'Passes courtes et matériel franchi en marchant.',harder:'Alterner réellement les côtés et ajuster le dosage à la course, sans obligation de jouer en une touche.'},
 'receive-back':{family:'duel',task:'Protéger dos au jeu puis remettre ou se retourner selon la pression réelle.',observe:'Le corps protège le ballon côté opposé au défenseur ; le soutien reste visible.',question:'Le défenseur te laisse-t-il te retourner ou faut-il remettre ?',correction:'Rejouer avant réception avec un défenseur d’abord retardé, puis actif.',invariant:'Le retournement n’est jamais obligatoire ; une remise qui préserve le ballon est une décision valable.',easier:'Pression déclenchée après le premier contact.',harder:'Défenseur actif dès la passe et choix libre du côté de sortie.'},
 'escape-turn':{family:'duel',task:'Quitter la pression par un contrôle orienté, une conduite ou une passe de sécurité.',observe:'Le premier contact éloigne le ballon du défenseur sans supprimer le soutien.',question:'Où est la sortie avant même que la passe arrive ?',correction:'Rejouer le service du même côté et faire identifier une porte libre avant le contrôle.',invariant:'Conserver une solution de retour ; ne pas exiger une feinte ou un côté de sortie identiques à chaque passage.',easier:'Service lent et défenseur retardé.',harder:'Changer l’angle du service et laisser l’adversaire fermer la sortie de son choix.'},
 'rondo-direction':{family:'possession',task:'Trouver une passe au-delà de la pression quand la fenêtre existe ; conserver autour autrement.',observe:'La passe traversante atteint un partenaire disponible et permet de garder le ballon.',question:'La fenêtre était-elle ouverte au départ du ballon ?',correction:'Figer avant une passe forcée et montrer le soutien extérieur pour préparer une nouvelle fenêtre.',invariant:'Aucun nombre de passes préalable obligatoire et aucune passe forcée entre deux défenseurs.',easier:'Touches libres et zone légèrement agrandie.',harder:'Laisser les défenseurs modifier leur alignement sans changer le nombre de conservateurs.'},
 'possession-neutral':{family:'possession',task:'Conserver en utilisant les appuis neutres pour trouver un joueur libre.',observe:'L’appui se déplace hors de l’ombre et change immédiatement d’équipe à la récupération.',question:'L’appui te libère-t-il une solution ou attire-t-il tout le monde au ballon ?',correction:'Rejouer une réception avec l’appui décalé, sans imposer de le servir.',invariant:'Au moins un neutre ; il ne défend pas contre l’équipe qui vient de récupérer.',easier:'Touches libres pour tous, priorité aux angles de passe.',harder:'Demander une prise d’information avant réception, puis observer sans bonus obligatoire.'},
 'possession-endzones':{family:'opposition',task:'Marquer par une réception maîtrisée dans la zone cible adverse sur un appel.',observe:'Le receveur entre au bon moment plutôt que d’attendre dans la zone cible.',question:'Le porteur est-il prêt à donner quand tu démarres ?',correction:'Revenir avant l’appel et laisser le passeur montrer le moment où la passe devient possible.',invariant:'Pas de joueur stationné en cible ; la zone reste défendable et le point exige une maîtrise du ballon.',easier:'Élargir la cible sans y protéger le receveur.',harder:'Défense libre d’accompagner et de changer sa hauteur.'},
 'break-lines':{family:'opposition',task:'Franchir une ligne par passe ou conduite, puis exploiter la réception vers la cible.',observe:'La réception au-delà d’un tiers permet une action utile, pas une passe aussitôt rendue sous pression.',question:'Peux-tu franchir directement ou faut-il d’abord déplacer l’adversaire ?',correction:'Figer avant le franchissement et décaler le receveur pour qu’il voie une suite.',invariant:'Les joueurs peuvent changer de tiers ; aucun circuit obligé avec une passe dans chaque zone.',easier:'Départ sous pression retardée et touches libres.',harder:'Retirer le bonus de franchissement et observer la progression spontanée.'},
 'attract-release':{family:'possession',task:'Attirer un opposant pour transmettre au partenaire qu’il vient de libérer.',observe:'Le porteur donne avant d’être enfermé et le receveur s’écarte réellement de la pression.',question:'Quel adversaire as-tu déplacé, et quel partenaire est devenu libre ?',correction:'Rejouer la fixation à vitesse réduite ; arrêter avant que les deux défenseurs ne ferment toutes les sorties.',invariant:'Fixer ne signifie pas attendre le contact. Un soutien doit rester accessible.',easier:'Espace légèrement agrandi et touches libres.',harder:'Défense libre de ne pas sortir ; le porteur peut alors progresser ou conserver.'},
 'build-three':{family:'opposition',task:'Élargir la relance pour dépasser la première pression et atteindre la cible opposée.',observe:'Les premiers soutiens donnent plusieurs angles sans s’aligner sur une même passe.',question:'Quelle largeur oblige le presseur à choisir ?',correction:'Repartir du fond en décalant un soutien bas et un relais plus haut.',invariant:'Les couloirs sont des repères de largeur ; tous les joueurs peuvent les quitter pour offrir un soutien.',easier:'Pression retardée sur la première réception.',harder:'Départs alternés et pressing libre dès la passe initiale.'},
 'build-pivot':{family:'opposition',task:'Utiliser le pivot quand il peut jouer la suite, ou contourner si sa réception serait piégée.',observe:'Le pivot voit la pression et garde une remise disponible avant la passe.',question:'Le pivot peut-il jouer après réception ou est-il seulement libre avant la passe ?',correction:'Figer avant le service au pivot et montrer son adversaire proche et une remise possible.',invariant:'Appui de liaison présent, non protégé ; son utilisation n’est pas obligatoire.',easier:'Retarder l’intervention sur la première réception du pivot.',harder:'Pression active et possibilité de contourner librement le pivot.'},
 'build-switch':{family:'opposition',task:'Sortir vers l’une des deux cibles en déplaçant la pression si nécessaire.',observe:'Le choix de sortie suit le déplacement réel des défenseurs.',question:'Quelle cible est accessible maintenant, pas celle prévue au départ ?',correction:'Rejouer le départ avec la même pression et laisser identifier la cible opposée.',invariant:'Quatre mini-buts et deux sens de jeu ; ne pas annoncer une seule sortie obligatoire.',easier:'Défense déclenchée après la première passe.',harder:'Pressing libre, y compris fermeture de la première sortie choisie.'},
 'thirdman-depth':{family:'opposition',task:'Utiliser une remise pour servir un troisième partenaire lancé derrière une ligne.',observe:'Le troisième part pendant la relation avec l’appui et reçoit face à la cible.',question:'Qui peut recevoir face au jeu si l’appui reçoit dos au jeu ?',correction:'Rejouer avant la première passe en retardant l’appel profond jusqu’au moment utile.',invariant:'Au moins trois partenaires utiles ; garder le choix du jeu direct si la ligne est ouverte.',easier:'Première pression retardée, touches libres pour la remise.',harder:'Le défenseur choisit de suivre l’appui ou la profondeur ; adapter la suite.'},
 'forward-runs':{family:'transition',task:'Recevoir dans la cible sur une course déclenchée quand le passeur peut jouer.',observe:'L’appel conserve une trajectoire visible et ne part pas avant que le porteur puisse donner.',question:'Quel indice chez le passeur déclenche ton appel ?',correction:'Revenir avant son contrôle et synchroniser ouverture du corps et départ de la course.',invariant:'Pas d’attente permanente dans la cible ; si la passe est fermée, conserver reste possible.',easier:'Cible plus large et service sans pression immédiate.',harder:'Défense libre d’avancer ou de suivre la profondeur.'},
 'wide-isolate':{family:'duel',task:'Servir un joueur large puis choisir duel, combinaison ou retour selon l’opposition.',observe:'Le soutien accompagne à distance utile sans fermer le couloir de conduite.',question:'Es-tu vraiment en un contre un ou le deuxième défenseur ferme-t-il déjà le côté ?',correction:'Rejouer avec le soutien décalé à l’intérieur et laisser le receveur choisir.',invariant:'Aucun dribble obligatoire ; deux cibles dans chaque sens permettent de sortir du côté fermé.',easier:'Pression retardée sur le joueur large.',harder:'La couverture intervient librement ; autoriser le retour et le changement de cible.'},
 underlap:{family:'finishing',task:'Fixer à l’extérieur puis trouver une course intérieure si le défenseur libère le demi-espace.',observe:'Le soutien part à l’intérieur au bon moment sans arriver dans la trajectoire du porteur.',question:'Quelle zone le défenseur libère-t-il en fermant l’extérieur ?',correction:'Rejouer le déclenchement de l’appel après la fixation, avec une solution de retour maintenue.',invariant:'La course intérieure reste un choix ; ne pas imposer une passe dans une ligne fermée.',easier:'Défenseur retardé et service côté annoncé.',harder:'Le défenseur peut fermer l’intérieur ; le porteur peut poursuivre sur le côté.'},
 'box-combine':{family:'finishing',task:'Créer une frappe face au but par remise, retournement ou passe dans un intervalle.',observe:'Le joueur qui donne se redéplace et les soutiens offrent deux hauteurs distinctes.',question:'La remise ouvre-t-elle réellement la frappe ?',correction:'Rejouer la passe d’appui avec un soutien décalé, sans exiger une remise si le tir direct est ouvert.',invariant:'Supériorité offensive réelle et au moins trois partenaires de combinaison ; ne pas empiler tous les joueurs devant le gardien.',easier:'Pression retardée sur l’appui et contrôle autorisé.',harder:'Défense active et choix entre jeu direct et combinaison.'},
 'finish-opposition':{family:'finishing',task:'Finir une action face à un défenseur actif ou transmettre si celui-ci ferme le tir.',observe:'Le choix de frappe tient compte du défenseur et du gardien, pas d’une zone imposée.',question:'Qui ferme ton angle : le défenseur ou le gardien ?',correction:'Rejouer l’avant-dernière touche en laissant une vraie possibilité de passe.',invariant:'L’opposition est réelle dès le départ annoncé ; le tir n’est pas obligatoire si la ligne est fermée.',easier:'Défenseur retardé au premier contrôle.',harder:'Varier l’angle du service et laisser le défenseur intervenir dès la passe.'},
 'far-post':{family:'finishing',task:'Occuper des zones complémentaires sur centre et faire arriver le joueur éloigné au second poteau.',observe:'L’arrivée éloignée est lancée au moment du centre, pas déjà immobile devant le gardien.',question:'Qui occupe le second poteau quand le ballon part du côté opposé ?',correction:'Replacer le joueur éloigné en retrait et rejouer son départ au moment où le centreur peut lever la tête.',invariant:'Un centreur, une arrivée proche et une arrivée éloignée ; la défense reste libre de suivre les appels.',easier:'Centre au sol et côté de départ connu.',harder:'Alterner côté et type de centre selon les espaces réellement laissés.'},
 'finish-rebound':{family:'finishing',task:'Préparer une seconde action sur ballon repoussé sans abandonner l’équilibre derrière le tir.',observe:'Un soutien se tient derrière et hors de l’alignement du tir pour recevoir un ballon repoussé.',question:'Si le gardien repousse maintenant, qui joue le prochain ballon ?',correction:'Figer avant le tir ; échelonner un soutien puis rejouer la seconde action.',invariant:'Gardien nécessaire et ballon vivant après déviation ; aucune charge sur un gardien qui maîtrise le ballon.',easier:'Service de départ annoncé et opposition retardée.',harder:'Gardien libre de bloquer, dévier ou relancer ; ne pas annoncer la zone du rebond.'},
 'press-goalkick':{family:'opposition',task:'Les bleus sortent vers les mini-buts ; les rouges récupèrent pour attaquer le grand but.',observe:'Le premier presseur oriente pendant que la couverture ferme la passe intérieure.',question:'Quel soutien devient dangereux si tu presses seul le gardien ?',correction:'Rejouer la première passe et répartir pression, couverture et fermeture du relais.',invariant:'Un gardien bleu au grand but et deux mini-buts de sortie. Les rôles ne sont pas ceux d’un jeu symétrique.',easier:'Un seul déclencheur annoncé sur la première réception.',harder:'Le gardien varie sa première passe et les presseurs choisissent leur déclencheur.'},
 'press-cover-three':{family:'opposition',task:'Défendre en répartissant pression, couverture et équilibre du côté éloigné.',observe:'Les trois responsabilités changent avec le ballon sans que deux joueurs abandonnent simultanément l’intérieur.',question:'Qui prend l’équilibre quand ton partenaire devient presseur ?',correction:'Figer sur un changement de côté et faire nommer les trois rôles avant de rejouer.',invariant:'Au moins trois défenseurs réellement présents ; ne pas prétendre travailler trois rôles avec seulement deux défenseurs.',easier:'Circulation latérale annoncée et rythme modéré.',harder:'La circulation peut revenir à l’intérieur ou renverser sans annonce.'},
 'block-two-lines':{family:'opposition',task:'Protéger l’espace entre les lignes tout en pouvant avancer sur une passe adverse.',observe:'La deuxième ligne accompagne la sortie de la première sans créer une coupure.',question:'L’espace derrière le premier presseur est-il encore protégé ?',correction:'Rejouer la passe qui a séparé les lignes, en corrigeant leur déplacement commun.',invariant:'Au moins quatre défenseurs pour matérialiser deux lignes ; les tiers ne limitent pas les déplacements.',easier:'Départs identiques et circulation adverse plus lente.',harder:'L’adversaire varie progression courte et passe derrière la première ligne.'},
 'defend-depth':{family:'opposition',task:'Empêcher une réception dans la cible en ajustant sa hauteur à la pression sur le passeur.',observe:'Le défenseur contrôle ballon et course, sans reculer automatiquement sur chaque passe.',question:'Le porteur peut-il jouer long maintenant ou est-il réellement pressé ?',correction:'Rejouer un même appel avec un passeur pressé puis libre pour comparer les ajustements.',invariant:'Cible défendable et appels libres ; ne pas transformer la profondeur en zone interdite aux défenseurs.',easier:'Un côté de départ et une menace profonde annoncés.',harder:'Passeur libre de jouer court ou profond selon la pression.'},
 'defend-cross':{family:'finishing',task:'Cadrer le centreur, protéger l’intérieur et traiter la zone de retrait avec le gardien.',observe:'Les défenseurs gardent ballon et adversaire dans leur champ visuel et annoncent les prises en charge.',question:'Qui protège le retrait quand tu accompagnes l’appel au premier poteau ?',correction:'Figer avant le centre et attribuer pression du côté, défense axiale et retrait.',invariant:'Gardien actif et plusieurs défenseurs de surface ; ne pas imposer une sortie du gardien sur tous les centres.',easier:'Centre au sol, côté connu et vitesse maîtrisée.',harder:'Le centreur choisit centre direct, retrait ou conservation selon la défense.'},
 'defend-outnumbered':{family:'duel',task:'Retarder une attaque en supériorité et protéger la passe axiale avant de chercher le gain.',observe:'Le proche ralentit ; la couverture ne sort pas sur le même porteur.',question:'Quel danger dois-tu retarder avant de tenter de récupérer ?',correction:'Rejouer l’entrée de l’attaque en protégeant d’abord la ligne vers la cible.',invariant:'Supériorité offensive et au moins deux défenseurs pour une couverture ; les appuis neutres ne doivent pas annuler le surnombre.',easier:'Attaque à vitesse maîtrisée au départ.',harder:'L’attaque peut varier le côté de fixation et déclencher plus tôt sa passe.'},
 'recovery-firstpass':{family:'transition',task:'Après récupération, quitter la pression avec une passe ou une conduite maîtrisée.',observe:'Le nouveau porteur regarde avant d’accélérer et un partenaire offre une sécurité.',question:'Quelle solution t’évite de reperdre immédiatement le ballon ?',correction:'Revenir au gain du ballon et faire nommer une solution proche et une solution vers l’avant.',invariant:'Pas de passe vers l’avant obligatoire ni de minimum de passes avant la progression.',easier:'Première pression retardée après récupération.',harder:'L’équipe qui perd réagit immédiatement ; le porteur peut choisir de sécuriser.'},
 'counter-wide':{family:'transition',task:'Exploiter la récupération par des courses en largeur et profondeur, sans forcer le contre.',observe:'Les deux premiers soutiens n’attaquent pas le même couloir.',question:'Quelle course ouvre un passage à ton partenaire ?',correction:'Rejouer la récupération en séparant la course large du soutien axial.',invariant:'Les trois couloirs sont des repères ; aucune présence permanente obligatoire dans chacun.',easier:'Retour défensif retardé sur le premier ballon.',harder:'Défense libre de se replacer ; conserver si le passage se ferme.'},
 'secure-regain':{family:'possession',task:'Maîtriser le ballon gagné puis choisir le rythme utile avec les appuis neutres.',observe:'Le porteur choisit une solution accessible plutôt qu’une passe précipitée dans la densité.',question:'Faut-il accélérer maintenant ou d’abord sortir de la pression ?',correction:'Rejouer le gain avec une remise disponible puis demander de justifier le choix après l’action.',invariant:'L’appui change immédiatement de camp à la récupération ; aucune temporisation arbitraire obligatoire.',easier:'Touches libres et premier soutien proche.',harder:'Contre-pression immédiate et choix libre entre passe directe et sécurisation.'},
 'counterpress-escape':{family:'transition',task:'À la perte, fermer les sorties proches ; au gain, trouver une sortie hors de la densité.',observe:'Le presseur gêne le porteur pendant qu’un partenaire coupe une passe réellement disponible.',question:'Quelle sortie doit être fermée avant d’aller au ballon ?',correction:'Figer à la perte et replacer un seul partenaire dans la ligne à couper, puis rejouer.',invariant:'Le ballon reste en jeu au changement de statut. Pas d’objectif automatique de récupération en trois secondes.',easier:'Débuter avec des distances courtes entre partenaires et des touches libres.',harder:'Retirer les annonces de changement de possession et laisser les nouveaux porteurs sortir librement.'},
 'rest-defence':{family:'opposition',task:'Attaquer en gardant des joueurs capables de ralentir la transition adverse à la perte.',observe:'La couverture suit le ballon tout en contrôlant les premières sorties adverses.',question:'Si nous perdons ici, quelle passe adverse est la plus dangereuse ?',correction:'Figer pendant l’attaque et ajuster une position de couverture avant de rejouer la perte.',invariant:'Pas de joueur enfermé dans un tiers ni de nombre fixe derrière le ballon, mais une couverture réellement utile.',easier:'Faire repérer une seule sortie adverse prioritaire.',harder:'L’adversaire varie sa première sortie après gain, sans signal du coach.'},
 'retreat-delay':{family:'transition',task:'Ralentir le contre pour permettre le retour des partenaires entre le ballon et la cible.',observe:'Le premier défenseur ne se fait pas éliminer ; les retours protègent l’axe avant le marquage lointain.',question:'Quel délai peux-tu donner aux partenaires qui reviennent ?',correction:'Rejouer le départ du contre en corrigeant l’angle de recul et une course de retour intérieure.',invariant:'Le contre progresse dans le sens réel de l’équipe qui a récupéré ; pas de poursuite collective derrière le ballon.',easier:'Contre lancé à vitesse maîtrisée et largeur réduite.',harder:'Le porteur choisit passe ou conduite tandis que les retours restent libres.'},
 'throw-progression':{family:'restart',task:'Conserver la touche puis exploiter l’espace libéré par le premier appel.',observe:'Le soutien reste disponible après la réception et le lanceur rentre dans le jeu.',question:'Qui devient libre quand le premier appel attire son défenseur ?',correction:'Rejouer le lancer et la première remise, en décalant la solution suivante.',invariant:'Un lanceur et trois partenaires de champ utiles ; la touche réglementaire ne devient pas une passe au pied.',easier:'Défense retardée au contrôle de la première réception.',harder:'Défense active et choix libre entre remise, conduite et progression directe.'},
 'corner-secondball':{family:'restart',task:'Jouer la seconde action après corner et conserver une couverture contre la relance adverse.',observe:'Les joueurs hors du premier duel anticipent une zone de retombée sans tous attaquer le but.',question:'Qui peut jouer le ballon repoussé et qui protège le contre ?',correction:'Figer avant le premier duel et séparer les missions second ballon et couverture.',invariant:'Un seul ballon vivant ; gardien protégé lorsqu’il maîtrise et nouvelle livraison seulement après la fin de l’action.',easier:'Livraison au sol et zone de retombée annoncée.',harder:'Livraison variée et défense autorisée à relancer immédiatement après maîtrise.'},
 'freekick-restart':{family:'restart',task:'Choisir une remise rapide si une ligne est ouverte ou installer la relance si elle est fermée.',observe:'Le joueur regarde l’adversaire avant de poser son choix, sans attendre automatiquement le signal du coach.',question:'Peut-on jouer maintenant dans les conditions réglementaires ?',correction:'Rejouer le même arrêt avec une solution libre puis fermée, et comparer les décisions.',invariant:'Respecter la distance et les conditions de reprise annoncées ; un coup franc indirect exige une seconde touche avant le but.',easier:'Départ connu et opposition à distance réglementaire.',harder:'Varier le placement adverse sans annoncer si la reprise doit être rapide.'},
 'keeper-distribute':{family:'keeper',task:'Après maîtrise, le gardien choisit une relance utile ou sécurise avec un soutien.',observe:'Le gardien regarde les sorties avant la maîtrise définitive et ne relance pas sur un partenaire enfermé.',question:'Quel partenaire peut poursuivre l’action après ta distribution ?',correction:'Figer après la prise de balle et montrer une solution immédiate et une solution de sécurité.',invariant:'Gardien réel ; aucune distribution imposée si la prise de balle n’est pas maîtrisée.',easier:'Sortie annoncée et pression retardée sur le receveur.',harder:'Les adversaires choisissent leur contre-pression ; le gardien garde le droit de temporiser.'},
 'duel-renforts':{family:'duel',task:'Passer de 1 contre 1 à 2 contre 1 puis 2 contre 2, avec un seul ballon et un contre possible.',observe:'Le nouvel entrant occupe un angle utile et les défenseurs changent de rôle au renfort.',question:'Le rapport vient de changer : peux-tu encore attaquer seul ?',correction:'Rejouer l’entrée du renfort en laissant un intervalle entre les deux signaux.',invariant:'Quatre joueurs de champ au maximum par vague, un gardien et deux entrées annoncées ; fin à 20 secondes, but ou sortie.',easier:'Renfort offensif annoncé et second signal plus tardif.',harder:'Le coach varie le moment du second renfort, sans dépasser la durée de vague.'},
 'rondo-expand':{family:'transition',task:'Sortir du 5 contre 2 puis conserver en 8 contre 5 après récupération bleue.',observe:'Un extérieur offre déjà une ligne de sortie à l’instant de l’interception.',question:'Quelle passe te sort du petit carré dès la récupération ?',correction:'Revenir à l’interception et décaler deux extérieurs à des angles différents.',invariant:'Exactement treize joueurs et un ballon : cinq rouges, deux bleus intérieurs et six bleus extérieurs. Ne pas adapter à douze ou quatorze en ajoutant un pion.',easier:'Touches libres et carré intérieur légèrement agrandi.',harder:'Réduire le petit carré seulement si la première passe extérieure reste réalisable.'},
 'possession-quadrants':{family:'possession',task:'Relier les appuis de bout en ajustant son angle dans son quadrant.',observe:'Le receveur prépare une passe suivante sans quitter son secteur.',question:'Comment changer ton angle tout en restant dans ton quadrant ?',correction:'Figer avant réception et déplacer le receveur dans son secteur, pas le défenseur hors de sa zone.',invariant:'Exactement onze joueurs : quatre contre quatre, deux appuis de bout et un central protégé. Le carré central reste de 3 × 3 m.',easier:'Touches libres et rythme de circulation maîtrisé.',harder:'Opposition réelle dans chaque quadrant sans libérer les secteurs ni supprimer l’appui central.'},
 'video-bounce-2v2':{family:'duel',task:'Utiliser son appui de couleur pour attaquer l’un des deux mini-buts, ou conserver si la passe est fermée.',observe:'Le partenaire intérieur arrive décalé sur la remise, face à une cible accessible.',question:'Quel mini-but est ouvert après la remise de ton appui ?',correction:'Rejouer la passe vers l’appui avec le second intérieur à une autre hauteur.',invariant:'Deux intérieurs et un appui par couleur ; les appuis ne sont pas neutres. Les autres tournent hors du terrain après chaque vague.',easier:'Touches libres et pression retardée sur la première réception.',harder:'Les défenseurs ferment l’appui ou une cible au choix ; aucune remise obligatoire pour marquer.'},
 'video-coordination-shot':{family:'coordination',task:'Servir le relais, franchir les haies sans ballon, remettre vers le central puis conduire et frapper.',observe:'Chaque transmission attend un partenaire équilibré et la frappe suit un dernier contact maîtrisé.',question:'Ton partenaire a-t-il fini ses appuis et peut-il recevoir maintenant ?',correction:'Rejouer à allure lente sans saut imposé ; séparer la sortie du matériel de la remise.',invariant:'Un côté et un ballon actifs, cinq postes de champ et un gardien ; retours extérieurs et nouvelle frappe seulement quand le gardien est prêt.',easier:'Franchissement marché, contrôle autorisé et côté de départ connu.',harder:'Alterner les côtés et ouvrir l’angle du dernier contact, sans ajouter un défenseur ni accélérer la cadence.'}
};

// Réparations éditoriales : les consignes courtes décrivent désormais les mêmes
// postes et le même type d'opposition que le moteur graphique.
const exerciseRuleRepairs={
 passes:['Installer trois postes par circuit, un ballon par circuit ; les joueurs en plus doublent le départ hors des passes.','Contrôler vers le prochain poste, transmettre puis rejoindre le poste libéré ; tourner aussi le poste doublé.','Changer le sens à la pause ; conserver le contrôle si le service ne permet pas une remise directe.'],
 'scan-receive':['Installer trois postes par circuit et un ballon par circuit ; les suivants attendent derrière le départ.','Regarder le prochain poste avant de recevoir puis orienter le contrôle vers la passe suivante.','Après la passe, rejoindre le poste libéré ; changer le sens seulement au signal avant un nouveau départ.'],
 finish:['Le coach sert l’attaque vers le but ou la porte indiquée dans l’installation ; les défenseurs présents protègent la cible.','Le receveur choisit contrôle orienté, remise ou frappe selon la pression ; annoncer si le défenseur intervient au contrôle ou dès la passe.','Après but, sortie ou maîtrise du gardien, replacer tout le groupe avant de servir ; inverser les fonctions à la pause.'],
 'press-goalkick':['Le gardien bleu démarre dans le grand but à gauche ; les bleus cherchent les deux mini-buts de sortie à droite.','Les rouges déclenchent sur le signal annoncé puis attaquent le grand but après récupération.','À chaque fin d’action, repartir du gardien une fois les joueurs replacés ; inverser les fonctions entre séries.']
};
for(const e of trainingExercises){
 const p=exercisePedagogy[e.id];if(!p)continue;
 e.success=p.observe;e.easier=p.easier;e.harder=p.harder;
 if(exerciseRuleRepairs[e.id])e.rules=exerciseRuleRepairs[e.id];
 if(e.id==='finish')e.method='Situation';
}
// Les acteurs minimums protègent le sens de la fiche, même si l'aire tient.
const exerciseActorRequirements={triangle:{minAttackers:3},'thirdman-depth':{minAttackers:3},cover:{minDefenders:2},block:{minDefenders:3},'press-cover-three':{minDefenders:3},'block-two-lines':{minDefenders:4},cutback:{minAttackers:3,minTeamAttackers:3},'far-post':{minAttackers:3,minTeamAttackers:3},'box-combine':{minAttackers:3,minTeamAttackers:3},'defend-cross':{minDefenders:3},'keeper-feet':{minAttackers:2},'keeper-distribute':{minDefenders:2},'defend-outnumbered':{minDefenders:2}};
for(const [id,requirements]of Object.entries(exerciseActorRequirements))if(bibleKnowledge[id]?.format)Object.assign(bibleKnowledge[id].format,requirements);

function bibleExerciseDose(exercise,session={}){
 const p=exercisePedagogy[exercise.id],family=p?.family||'opposition',light=session.coachingLoad==='light';
 const settings={activation:[120,45],recovery:[180,30],technical:[120,45],possession:[150,60],opposition:[150,60],transition:[90,75],duel:[30,45],finishing:[45,45],restart:[90,60],keeper:[30,60],'keeper-feet':[90,60],coordination:[60,60]};
 let [workSeconds,restSeconds]=settings[family]||settings.opposition;
 const younger=/\bU\s*1[2-5]\b/i.test(session.category||'')||(!session.category&&session.age<=15),novice=session.level==='discovery';
 if(younger||novice)workSeconds=Math.round(workSeconds*.8);
 else if(session.level==='advanced'&&['possession','opposition'].includes(family))workSeconds=Math.round(workSeconds*1.2);
 if(light){workSeconds=Math.round(workSeconds*.7);restSeconds+=15;}
 if(exercise.id==='duel-renforts')workSeconds=Math.min(workSeconds,20);
 if(exercise.id==='video-bounce-2v2')workSeconds=Math.min(workSeconds,30);
 return {family,workSeconds:Math.max(12,workSeconds),restSeconds,loadLabel:light?'Charge allégée':'Charge habituelle',guidance:family==='recovery'?'Aucune charge supplémentaire : marche, échanges doux et bilan.':family==='activation'?'Monter progressivement en disponibilité ; ne pas rechercher la fatigue.':family==='technical'?'Garder le contrôle et la précision ; réduire le rythme avant de limiter les touches.':['finishing','keeper','coordination','restart'].includes(family)?'Chaque répétition attend la remise en place et la disponibilité du gardien lorsqu’il est présent. Une réserve de ballons ne justifie pas des départs en rafale.':'La difficulté de décision et la charge physique sont distinctes. Réduire le temps actif et conserver les pauses si les distances ou la qualité se dégradent.'};
}
function bibleExerciseActivity(exercise,group){
 const family=exercisePedagogy[exercise.id]?.family,field=group.players-group.keepers,template=group.template;
 let waiting=group.rotatingKeepers||0,engaged=group.players-waiting;
 if(template==='circuit'&&!['warm','cool'].includes(exercise.id)){engaged=Math.min(group.players,3*group.material.activeBalls);waiting=group.players-engaged;}
 if(exercise.id==='wall-pass'){engaged=Math.min(group.players,3);waiting=group.players-engaged;}
 if(exercise.id==='video-bounce-2v2'){engaged=Math.min(6,group.players);waiting=group.players-engaged;}
 if(exercise.id==='video-coordination-shot'){engaged=Math.min(6,group.players);waiting=group.players-engaged;}
 if(exercise.id==='duel-renforts'){engaged=Math.min(field,4)+group.activeKeepers;waiting=group.players-engaged;}
 return {engaged,waiting,field,format:group.roles,description:exercise.id==='wall-pass'?'Trois postes dans la chaîne ; '+waiting+' suivant(s) au départ. Tourner après chaque chaîne, retours extérieurs séparés.':exercise.id==='video-bounce-2v2'?'4 intérieurs + 2 appuis de couleur ; les suivants entrent après chaque fin de vague.':exercise.id==='video-coordination-shot'?'5 postes de champ + 1 gardien ; trois joueurs de champ exécutent la chaîne, le côté opposé reste prêt pour la vague suivante.':exercise.id==='duel-renforts'?'De 2 à 4 joueurs de champ dans l’action + 1 gardien ; les suivants restent hors des trajectoires.':template==='circuit'&&!['warm','cool'].includes(exercise.id)?group.material.activeBalls+' circuit(s) à trois postes ; '+waiting+' suivant(s) au départ, rotation à chaque chaîne.':waiting?'Gardiens supplémentaires en rotation ; joueurs de champ en jeu selon les rôles annoncés.':family==='recovery'?'Tous participent aux échanges et au bilan, sans opposition.':'Tous ont un rôle dans l’organisation ; cela ne signifie pas un effort maximal permanent.'};
}
function bibleExerciseRotation(exercise,group){
 const family=exercisePedagogy[exercise.id]?.family;
 if(exercise.id==='underlap')return 'À la pause, permuter porteur de côté, soutien en course intérieure et solution de retour. Inverser attaque et défense entre séries ; le gardien conserve son rôle.';
 if(['cutback','far-post'].includes(exercise.id))return 'À la pause, permuter centreur, arrivée proche et arrivée éloignée parmi les attaquants ; au changement de séquence, inverser attaque et défense. Le gardien conserve son rôle.';
 if(['finish','box-combine','finish-opposition','finish-rebound','defend-cross'].includes(exercise.id))return 'Replacer après chaque action terminée ; faire varier les joueurs servis et les zones de départ. Inverser attaque et défense à la pause, sans transformer un gardien en joueur de champ.';
 if(family==='keeper')return 'Les joueurs de champ alternent service, attaque et opposition à la pause. Le gardien reste gardien ; s’ils sont plusieurs, les faire entrer à tour de rôle après une action terminée, jamais pendant un tir.';
 if(family==='keeper-feet')return 'À la pause, les joueurs de champ échangent soutien et pressing. Permuter les gardiens disponibles séparément ; le gardien actif reste identifié dans la relance.';
 if(['cpa-attack','cpa-defence','corner-secondball'].includes(exercise.id))return 'À la pause, changer le tireur et répartir de nouveau premier ballon, second ballon et couverture. Alterner attaque et défense entre séries ; ne relivrer qu’après remise en place complète.';
 if(['touch','throw-progression'].includes(exercise.id))return 'Après chaque répétition terminée, le lanceur entre dans le jeu et un autre partenaire prend la touche ; répartir de nouveau court, profondeur et soutien. Changer les équipes de départ à la pause.';
 if(exercise.id==='freekick-restart')return 'Changer le joueur chargé de la reprise après une action terminée et alterner les côtés. Inverser les fonctions à la pause, sans remettre un second ballon dans l’action.';
 if(family==='duel')return 'Terminer chaque opposition sur but, sortie ou arrêt annoncé ; replacer le ballon avant le départ suivant. À la pause, échanger attaque et défense et faire tourner les appuis éventuels.';
 if(group.teams.neutral)return 'À la fin de chaque séquence, échanger les appuis neutres avec des joueurs des deux équipes, dans un ordre fixe. À chaque récupération, les appuis jouent immédiatement avec les nouveaux porteurs.';
 return group.rotation;
}
function bibleExerciseOutsideRotation(context){
 if(!context.offPlayers)return '';
 const field=context.activePlayers-context.activeKeepers,outField=context.offFieldPlayers,outKeepers=context.offKeepers;
 const parts=[context.offPlayers+' hors exercice : '+outField+' de champ et '+outKeepers+' G.'];
 if(outField>0)parts.push('À la fin de chaque répétition, '+Math.min(outField,field)+' joueur(s) de champ sort(ent) et autant entrent, dans un ordre fixe ; garder les mêmes rôles et le même effectif actif.');
 if(outKeepers>0&&context.activeKeepers>0)parts.push('Permuter un gardien à la fin de la répétition, séparément des joueurs de champ.');
 else if(outKeepers>0)parts.push('Aucun gardien actif dans cette séquence : prévoir une activité encadrée distincte, aucun échange avec un joueur de champ.');
 parts.push('Entre les passages : récupération et observation hors des trajectoires. Pour une activité parallèle, vérifier espace, matériel et encadrement avant de la lancer.');
 return parts.join(' ');
}

function bibleExerciseEssentials(exercise,context,sequence,groupIndex=0){
 const root=el('section','exercise-essentials');root.setAttribute('aria-label','Repères de l’exercice');
 if(!context.valid)return root;
 const g=context.plan.groups[groupIndex]||context.plan.groups[0],p=exercisePedagogy[exercise.id];if(!g||!p)return root;
 const scenario=bibleCoachScenario(exercise,g,sequence?.index?sequence.index-1:0),activity=bibleExerciseActivity(exercise,g),dose=bibleExerciseDose(exercise,context.session);
 const card=(label,text)=>{const section=el('section');section.append(el('h4','',label),el('p','',text));root.append(section);return section;};
 card('But pour les joueurs',p.task).append(el('p','exercise-score',scenario.score));
 card('Ce qui montre un progrès',p.observe).append(el('p','exercise-question','À demander : « '+p.question+' »'));
 const organisation=card('Groupe & rotations',g.players+' affectés à cet atelier · '+activity.engaged+' dans le dispositif'+(activity.waiting?' · '+activity.waiting+' en attente / rotation':''));
 organisation.append(el('p','',activity.description),el('p','',g.rotation));
 if(context.plan.groups.length>1)organisation.append(el('p','hint',context.plan.groups.length+' ateliers simultanés ; matériel compté pour tous les ateliers. Les séries tournent sur le même signal du coach.'));
 if(context.offPlayers)organisation.append(el('p','exercise-outside',bibleExerciseOutsideRotation(context)));
 const intervals=sequence?.intervals||[],rests=intervals.filter(i=>i.restSeconds>0),rhythm=intervals.length>1||rests.length?intervals.length+' répétition(s) de '+[...new Set(intervals.map(i=>bibleTime(i.workSeconds)))].join(' à ')+(rests.length?' · récupération(s) de '+[...new Set(rests.map(i=>bibleTime(i.restSeconds)))].join(' à ')+', comprises dans la séquence':''):sequence?bibleTime(sequence.workSeconds)+' d’activité sur cette séquence':'Lire les durées dans le déroulé';
 const load=card('Rythme & intervention',dose.loadLabel+' · '+rhythm+(sequence?.restSeconds?' · puis '+bibleTime(sequence.restSeconds)+' de pause avant la séquence suivante.':'.'));
 const teaching=exercise.method==='Exercice'?'Montrer un passage lent, faire répéter et donner un retour sur un seul point.':exercise.method==='Situation'?'Laisser une tentative, questionner le choix puis rejouer le même problème.':'Observer une phase de jeu, intervenir brièvement à un arrêt utile puis laisser rejouer sans rappel.';
 load.append(el('p','exercise-teaching','Accompagnement · '+teaching),el('p','',dose.guidance),el('p','exercise-correction','Si cela bloque : '+p.correction));
 const invariant=el('p','exercise-invariant');invariant.append(el('strong','','À préserver · '),document.createTextNode(p.invariant));root.append(invariant);
 return root;
}
